// The app bundle's entry point: `main` hands the process to C+, and
// glass_music_ios_main never comes back — it calls UIApplicationMain, which owns
// the process from there. facet_uikit synthesizes both its delegate class
// and its scene delegate at runtime, so Info.plist NAMES the scene (every
// windowing API on iPadOS hangs off one) and must not name a storyboard
// (UIKit would wait for a nib facet has not got, and the screen stays
// black).

#import "glass_music_ios.h"   // generated by cpc into target/<triple>/debug/

int main(int argc, char *argv[]) {
    return glass_music_ios_main();
}
